function preToolUse(input) {
  if (!SHELL_TOOLS.has(input.tool_name)) return 0;
  const command = input.tool_input && input.tool_input.command;
  if (typeof command !== 'string') throw new Error('tool_input.command is missing');
  const cwd = workingDirectory(input);
  let findings = require('../scripts/classify-command.cjs').classify(command, { cwd });
  if (findings.some(f => f.kind === 'reference-change')) {
    const manifests = require('../scripts/check-manifests.cjs');
    const approvals = manifests.acceptedDecisionText(lib.activeRoot(cwd));
    findings = findings.filter(f => f.kind !== 'reference-change' || !f.edges.length || f.edges.some(e => !manifests.isApprovedEdge(approvals, e.from, e.to)));
  }
  if (!findings.length) return 0;
  process.stderr.write(`Blocked before execution (dependency and project-reference guard):\n- ${findings.map(describe).join('\n- ')}\n`);
  return 2;
}

function main(event) {
  run(event).then(
    code => {
      process.exitCode = code;
    },
    err => {
      const critical = CRITICAL.has(event);
      process.stderr.write(`[hook ${event}] ${critical ? 'blocked (fail closed)' : 'failed'}: ${err && err.message ? err.message : err}\n`);
      process.exitCode = critical ? 2 : 1;
    });
}

// Post-execution inspection of the ACTUAL files of the active repository/worktree; command text is never consulted.
// A bounded snapshot (content hash per relevant file, project-reference edges, HEAD) is kept per worktree in its
// own Git directory. The first observation baselines against HEAD; later observations report what changed since
// the previous one. Reference-graph changes count only while they differ from HEAD (committed history and
// reverted edits are not pending changes).

/** Reference-graph findings for one project file: (current Δ base) ∩ (current Δ HEAD), minus recorded approvals. */
function graphFindings(rel, current, base, head, hasHead, approvals, roleOf) {
  const name = path.posix.basename(rel).replace(/\.csproj$/i, '');
  const key = s => s.toLowerCase();
  const cur = new Map((current || []).map(e => [key(e), e]));
  const bas = new Map((base || []).map(e => [key(e), e]));
  const hd = new Map((head || []).map(e => [key(e), e]));
  const changes = [];
  if (current !== null && base === null && (!hasHead || head === null) && roleOf(name).kind !== 'test') {
    if (!manifests.isApprovedProject(approvals, name)) changes.push(`project ${name} added`);
  }
  if (current === null && base !== null && (!hasHead || head !== null) && roleOf(name).kind !== 'test') {
    if (!manifests.isApprovedProject(approvals, name)) changes.push(`project ${name} removed`);
  }
  for (const [k, to] of cur) {
    if (!bas.has(k) && (!hasHead || !hd.has(k)) && !manifests.isApprovedEdge(approvals, name, to)) changes.push(`${name} -> ${to} added`);
  }
  for (const [k, to] of bas) {
    if (!cur.has(k) && (!hasHead || hd.has(k)) && !manifests.isApprovedEdge(approvals, name, to)) changes.push(`${name} -> ${to} removed`);
  }
  if (!changes.length) return [];
  return [lib.finding('error', rel, `project reference graph changed without a recorded approval (Reserved): ${changes.join('; ')}`, OWNER_RESERVED)];
}

function parseProject(root, rel, source) {
  const text = lib.stripXmlComments(source === undefined ? lib.readText(root, rel) : source);
  const dir = path.posix.dirname(rel);
  const projectTag = lib.xmlElements(text, 'Project')[0];
  const sdk = (projectTag && projectTag.attrs.Sdk) || '';
  const packages = lib.xmlElements(text, 'PackageReference').map(e => ({
    id: e.attrs.Include || e.attrs.Update || '',
    version: e.attrs.Version || e.child.Version || '',
    versionOverride: e.attrs.VersionOverride || e.child.VersionOverride || '',
  }));
  // Only an Include adds a reference edge (Update/Remove items or a missing Include reference nothing).
  const projectRefs = lib.xmlElements(text, 'ProjectReference').filter(e => e.attrs.Include).map(e => {
    const include = e.attrs.Include.replace(/\\/g, '/');
    const target = path.posix.normalize(path.posix.join(dir, include));
    return { include, target, name: path.posix.basename(target).replace(/\.(cs|fs|vb)proj$/i, '') };
  });
  const frameworkRefs = lib.xmlElements(text, 'FrameworkReference').map(e => e.attrs.Include || '');
  return { rel, name: path.posix.basename(rel).replace(/\.(cs|fs|vb)proj$/i, ''), sdk, packages, projectRefs, frameworkRefs };
}

